  VALUES ('mv_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001',1,'0.1','{"constraints":[],"domain":"software_delivery","entity_types":[{"id":"change","name":"Change"}],"flows":[{"from":"start","id":"start_work","routing":{"probability":1,"type":"probability"},"to":"work"},{"from":"work","id":"work_end","routing":{"probability":1,"type":"probability"},"to":"end"}],"metrics":[],"model_id":"mdl_01M4YDQK00TA00000000000001","name":"Model A v1","nodes":[{"arrival":{"distribution":{"type":"constant","value":10},"max_entities":1},"entity_type":"change","id":"start","type":"source"},{"id":"work","requires":[{"resource_id":"worker","units":1}],"service_time":{"distribution":{"type":"constant","value":1}},"type":"process"},{"id":"end","type":"sink"}],"resources":[{"capacity":1,"id":"worker","name":"Worker","queue_discipline":"fifo","type":"human"}],"schema_version":"0.1","time_unit":"minute","views":{"2d":{},"3d":{}}}','sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e','usr_01M4YDQK00TA00000000000001');

-- The API creates runs, queued with nothing done, and their jobs.
RESET ROLE;
CREATE FUNCTION pg_temp.run_sql(id text, status text, extra_cols text, extra_vals text) RETURNS text LANGUAGE sql AS $$
  SELECT format($f$INSERT INTO twin.simulation_runs(id,organization_id,model_id,model_version_id,name,scenario_patch,config,seed,replications,
      engine_version,model_hash,effective_model_hash,config_hash,dataset_manifest_hash,dataset_bindings,execution_limits,created_by,status%s)
    VALUES (%L,'org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','run','[]','{}',7,2,'des-go-0.1.0','sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e','sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e','sha256:1111111111111111111111111111111111111111111111111111111111111111',
      'sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','[]','{"max_events":1000}','usr_01M4YDQK00TA00000000000001',%L%s)$f$, extra_cols, id, status, extra_vals)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.run_sql(text, text, text, text) TO PUBLIC;
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail(pg_temp.run_sql('sim_01M4YDQK00TA00000000000099', s, '', ''), '55000') FROM unnest(ARRAY['running','completed','failed','cancelled']) AS s;
SELECT pg_temp.must_fail(pg_temp.run_sql('sim_01M4YDQK00TA00000000000099', 'queued', ','||c, ','||v), '55000') FROM (VALUES
  ('cancellation_requested', 'true'), ('completed_replications', '1'), ('events_processed', '1'),
  ('progress_revision', '1'), ('event_budget_reserved', '1'), ('started_at', 'now()'), ('execution_deadline_at', 'now()'),
  ('finished_at', 'now()'), ('error', $$'{"code":"X","message":"x","retryable":false}'$$)) AS t(c, v);
SELECT pg_temp.run_sql(r, 'queued', '', '') FROM unnest(ARRAY['sim_01M4YDQK00TA00000000000001','sim_01M4YDQK00TA00000000000002','sim_01M4YDQK00TA00000000000003','sim_01M4YDQK00TA00000000000004','sim_01M4YDQK00TA00000000000005','sim_01M4YDQK00TA00000000000006','sim_01M4YDQK00TA00000000000007']) AS r \gexec
INSERT INTO twin.jobs(id,organization_id,type,status,payload,simulation_run_id) VALUES
  ('job_01M4YDQK00TA00000000000012','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000001'),
  ('job_01M4YDQK00TA00000000000013','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000002'),
  ('job_01M4YDQK00TA00000000000014','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000003'),
  ('job_01M4YDQK00TA00000000000015','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000004'),
  ('job_01M4YDQK00TA00000000000016','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000005'),
  ('job_01M4YDQK00TA00000000000017','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000006');
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
-- One job per run (double enqueue).
SELECT pg_temp.must_fail($q$INSERT INTO twin.jobs(id,organization_id,type,status,payload,simulation_run_id) VALUES ('job_01M4YDQK00TA00000000000099','org_01M4YDQK00TA00000000000000','simulation','queued','{}','sim_01M4YDQK00TA00000000000001')$q$, '23505');

-- The API only requests cancellation, advancing the revision; it never
-- moves a run's status, progress, budget or times itself.
SELECT pg_temp.must_fail(s, '55000') FROM unnest(ARRAY[
  $q$UPDATE twin.simulation_runs SET status='cancelled', finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET status='running', started_at=now(), execution_deadline_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET events_processed=5, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET completed_replications=1, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET event_budget_reserved=10 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET execution_deadline_at=now() WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET started_at=now() WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET finished_at=now() WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  -- a visible change that does not advance the revision, or a revision going back
  $q$UPDATE twin.simulation_runs SET cancellation_requested=true WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$
]) AS s;
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET status='failed', error='{"code":"X","message":"x","retryable":false}', finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$, '55000');
UPDATE twin.simulation_runs SET cancellation_requested=true, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000002')='queued 0 0 1 t f', 'the API requests a queued run''s cancellation: '||pg_temp.state('sim_01M4YDQK00TA00000000000002'));
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET progress_revision=0 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');
-- Not even the owner withdraws a cancellation request or skips the revision.
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET cancellation_requested=false, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET events_processed=3 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET completed_replications=1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET status='running', started_at=now(), execution_deadline_at=now() WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');
-- Nor moves a queued run straight to completed, or a running one back
-- without its job.
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET status='completed', completed_replications=2, finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000007'$q$, '55000');

-- The API cancels a queued job; the run follows at once (TEST-021).
SET LOCAL ROLE twin_api;
UPDATE twin.jobs SET status='cancelled' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000013';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000002')='cancelled 0 0 2 t t', 'a queued job''s cancellation cancels its run: '||pg_temp.state('sim_01M4YDQK00TA00000000000002'));
-- A final run is final for everyone (0001).
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000002'$q$, '55000');

-- The worker claims a job and starts the attempt: queued -> running.
SET LOCAL ROLE twin_worker;
UPDATE twin.jobs SET status='running', attempt=attempt+1, lease_token=lease_token+1, locked_at=now(), locked_by='w', lease_expires_at=now()+interval '30 seconds', heartbeat_at=now()
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('job_01M4YDQK00TA00000000000012','job_01M4YDQK00TA00000000000014','job_01M4YDQK00TA00000000000015','job_01M4YDQK00TA00000000000016','job_01M4YDQK00TA00000000000017');
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000001')='queued 0 0 0 f f', 'a claim leaves the run queued: '||pg_temp.state('sim_01M4YDQK00TA00000000000001'));
-- The worker never touches a queued run but to start it.
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET events_processed=1, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$, '55000');
UPDATE twin.simulation_runs SET status='running', started_at=now(), execution_deadline_at=now()+interval '5 minutes', event_budget_reserved=100,
    progress_revision=progress_revision+1
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('sim_01M4YDQK00TA00000000000001','sim_01M4YDQK00TA00000000000003','sim_01M4YDQK00TA00000000000004','sim_01M4YDQK00TA00000000000005','sim_01M4YDQK00TA00000000000006');
