  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000001')='running 1 40 2 f f', 'the worker writes progress: '||pg_temp.state('sim_01M4YDQK00TA00000000000001'));
-- ... advancing the revision with every visible change, within its budget;
-- the run's own moves to queued, failed or cancelled come from its job.
SELECT pg_temp.must_fail(s, '55000') FROM unnest(ARRAY[
  $q$UPDATE twin.simulation_runs SET events_processed=41 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET event_budget_reserved=199 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET status='queued', progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET status='cancelled', finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET status='failed', error='{"code":"X","message":"x","retryable":false}', finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.simulation_runs SET execution_deadline_at=now() WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$,
  -- a run completes only with its result
  $q$UPDATE twin.simulation_runs SET status='completed', completed_replications=2, finished_at=now(), progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$
]) AS s;
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET event_budget_reserved=1001 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001'$q$, '23514');

-- A result is stored only for its running run, reproducing its frozen
-- input, with its own digest; the trace all or none, under the run's
-- prefix, and named by the result.
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest) VALUES ('sim_01M4YDQK00TA00000000000007','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222')$q$, pg_temp.result('sim_01M4YDQK00TA00000000000007','sha256:2222222222222222222222222222222222222222222222222222222222222222',NULL)), '55000');
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest) VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222')$q$,
    jsonb_set(pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222',NULL), p, v)), '23514')
  FROM (VALUES ('{engine_version}'::text[], '"des-go-0.2.0"'::jsonb), ('{reproducibility,seed}', '8'), ('{reproducibility,replications}', '3'),
               ('{reproducibility,model_hash}', '"sha256:3333333333333333333333333333333333333333333333333333333333333333"'), ('{reproducibility,effective_model_hash}', '"sha256:3333333333333333333333333333333333333333333333333333333333333333"'),
               ('{reproducibility,config_hash}', '"sha256:3333333333333333333333333333333333333333333333333333333333333333"'), ('{reproducibility,dataset_manifest_hash}', '"sha256:3333333333333333333333333333333333333333333333333333333333333333"'),
               ('{reproducibility,result_digest}', '"sha256:3333333333333333333333333333333333333333333333333333333333333333"')) AS t(p, v);
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest) VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222')$q$,
    pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222',NULL) #- p), '23514')
  FROM (VALUES ('{engine_version}'::text[]), ('{reproducibility,seed}'), ('{reproducibility,config_hash}')) AS t(p);
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest,trace_artifact_id,trace_object_key,trace_content_hash,trace_size_bytes)
    VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222',%L,%L,%L,%s)$q$, pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222',a), a, k, h, coalesce(s::text,'NULL')), '23514')
  FROM (VALUES
    ('art_01M4YDQK00TA00000000000001', NULL, 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 10),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/t.json', NULL, 10),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/t.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', NULL),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/t.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 0),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/t.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 67108865),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000003/t.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 10),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 10),
    ('art_01M4YDQK00TA00000000000001', 'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001//t.json', 'sha256:3333333333333333333333333333333333333333333333333333333333333333', 10)
  ) AS t(a, k, h, s);
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest,trace_artifact_id,trace_object_key,trace_content_hash,trace_size_bytes)
    VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222','art_01M4YDQK00TA00000000000001','tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/t.json','sha256:3333333333333333333333333333333333333333333333333333333333333333',10)$q$, pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222',r)), '23514')
  FROM unnest(ARRAY[NULL, 'art_01M4YDQK00TA00000000000002']) AS r;
