INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest,trace_artifact_id,trace_object_key,trace_content_hash,trace_size_bytes)
  VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222','art_01M4YDQK00TA00000000000001'),'sha256:2222222222222222222222222222222222222222222222222222222222222222','art_01M4YDQK00TA00000000000001',
          'tenant/org_01M4YDQK00TA00000000000000/simulation-results/sim_01M4YDQK00TA00000000000001/art_01M4YDQK00TA00000000000001.json','sha256:3333333333333333333333333333333333333333333333333333333333333333',10);
-- A job completes only once its run has.
SELECT pg_temp.must_fail($q$UPDATE twin.jobs SET status='completed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000012'$q$, '55000');
UPDATE twin.simulation_runs SET status='completed', completed_replications=2, events_processed=80, finished_at=now(), progress_revision=progress_revision+1
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000001';
UPDATE twin.jobs SET status='completed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000012';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000001')='completed 2 80 3 f t', 'a completed run: '||pg_temp.state('sim_01M4YDQK00TA00000000000001'));
-- No other result, not even by the owner, once the run completed.
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest) VALUES ('sim_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222')$q$, pg_temp.result('sim_01M4YDQK00TA00000000000001','sha256:2222222222222222222222222222222222222222222222222222222222222222',NULL)), '55000');
SET LOCAL ROLE twin_worker;

-- A retried attempt puts the run back in the queue with its progress
-- reset; a failed one fails the run with the job's failure (TEST-020).
UPDATE twin.simulation_runs SET completed_replications=1, events_processed=7, progress_revision=progress_revision+1
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000003';
UPDATE twin.jobs SET status='queued', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL, error='{"code":"LEASE_EXPIRED","message":"x","retryable":true}'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000014';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000003')='queued 0 0 3 f f', 'a retry requeues the run: '||pg_temp.state('sim_01M4YDQK00TA00000000000003'));
UPDATE twin.jobs SET status='failed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL, error='{"code":"EVENT_BUDGET_EXCEEDED","message":"x","retryable":false}'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000015';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000004')='failed 0 0 2 f EVENT_BUDGET_EXCEEDED t', 'a failure fails the run: '||pg_temp.state('sim_01M4YDQK00TA00000000000004'));
-- A running run is cancelled only once its cancellation was requested.
SELECT pg_temp.must_fail($q$UPDATE twin.jobs SET status='cancelled', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000016'$q$, '55000');
SET LOCAL ROLE twin_api;
UPDATE twin.simulation_runs SET cancellation_requested=true, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000005';
-- No result for a run whose cancellation is requested (cancel vs complete).
SET LOCAL ROLE twin_worker;
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.simulation_results(run_id,organization_id,result,result_digest) VALUES ('sim_01M4YDQK00TA00000000000005','org_01M4YDQK00TA00000000000000',%L,'sha256:2222222222222222222222222222222222222222222222222222222222222222')$q$, pg_temp.result('sim_01M4YDQK00TA00000000000005','sha256:2222222222222222222222222222222222222222222222222222222222222222',NULL)), '55000');
UPDATE twin.jobs SET status='cancelled', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000016';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000005')='cancelled 0 0 3 t t', 'a requested cancellation ends the run: '||pg_temp.state('sim_01M4YDQK00TA00000000000005'));
-- A failure the job records without one (by hand) still fails the run with a failure.
RESET ROLE;
UPDATE twin.jobs SET status='failed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000017';
SELECT pg_temp.check(pg_temp.state('sim_01M4YDQK00TA00000000000006')='failed 0 0 2 f INTERNAL t', 'a failure without a record: '||pg_temp.state('sim_01M4YDQK00TA00000000000006'));

-- Any other role is refused, whatever privileges it is given.
GRANT SELECT, INSERT, UPDATE ON twin.simulation_runs TO twin_provisioner;
SET LOCAL ROLE twin_provisioner;
SELECT pg_temp.must_fail($q$UPDATE twin.simulation_runs SET cancellation_requested=true, progress_revision=progress_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='sim_01M4YDQK00TA00000000000007'$q$, '55000');
RESET ROLE;
REVOKE SELECT, INSERT, UPDATE ON twin.simulation_runs FROM twin_provisioner;
SELECT pg_temp.check(string_agg(status, ',' ORDER BY id)='completed,cancelled,queued,failed,cancelled,failed,queued', 'the runs ended as they did: '||string_agg(status, ',' ORDER BY id))
  FROM twin.simulation_runs WHERE organization_id='org_01M4YDQK00TA00000000000000';

ROLLBACK;
